from __future__ import annotations

import shlex

DEFAULT_SKILLS: dict[str, list[str]] = {
    "grill-with-docs": ["claude", "/grill-with-docs"],
    "tdd": ["claude", "/tdd"],
    "handoff": ["claude", "/handoff"],
}


def build_wrapper_script(
    wrapper_name: str,
    skill_name: str,
    command: list[str],
) -> str:
    command_text = " ".join(_quote_command_part(part) for part in command)
    shell_command = shlex.quote(f'exec {command_text} "$@"')
    quoted_skill = shlex.quote(skill_name)
    quoted_wrapper = shlex.quote(wrapper_name)
    return f"""#!/usr/bin/env sh
# Generated by {wrapper_name}. Edit the command list in the generator, not here.
set -eu

: "${{MEMANTO_SKILL_BACKEND:=local}}"

exec memanto-skill-memory wrap --skill {quoted_skill} --cwd "$PWD" -- \\
  sh -c {shell_command} {quoted_wrapper} "$@"
"""


def _quote_command_part(part: str) -> str:
    if part.startswith("/"):
        return '"' + part.replace('"', '\\"') + '"'
    return shlex.quote(part)
